function wbpSet(all){const s=(all||[]).find(m=>m.id===WBP_SID)||{};return{trial:s.trial==null?3:s.trial,contact:s.contact||'088902862338',pkgs:(Array.isArray(s.pkgs)&&s.pkgs.length===3)?s.pkgs:[{l:'1 Bulan',p:'Rp100.000'},{l:'6 Bulan',p:'Rp500.000'},{l:'1 Tahun',p:'Rp1.000.000'}],pay:s.pay||'DANA 088902862338 a.n. Darwati',locked:s.locked||[]};}
// ── sesi + kunci fitur (disimpan di server, ikut sesi member) ──
function wbpSave(m,st){const o=Object.assign({},m);delete o.password;o._locks=[...new Set([...(st.locked||[]),...(m.locked||[])])];localStorage.setItem(WBP_K_MEM,JSON.stringify(o));}
function wbpApplyLocks(){const s=wbpSess();WBP_LK=new Set(s&&!s.isAdmin?(s._locks||[]):[]);let st=$w('wbp-lkstyle');if(!st){st=document.createElement('style');st.id='wbp-lkstyle';document.head.appendChild(st);}const sel=WBP_FEATS.filter(f=>WBP_LK.has(f.key)).flatMap(f=>f.sel);st.textContent=sel.length?sel.join(',')+'{opacity:.4!important;position:relative}'+sel.map(x=>x+'::after').join(',')+"{content:'🔒';position:absolute;top:1px;right:2px;font-size:9px;pointer-events:none}":'';}
document.addEventListener('click',e=>{if(!WBP_LK.size||!e.target.closest)return;const bt=e.target.closest('button,[role=button],.ntab'),tx=bt?(bt.textContent||'').trim():'';for(const f of WBP_FEATS){if(!WBP_LK.has(f.key))continue;const hit=(f.sel&&f.sel.length&&e.target.closest(f.sel.join(',')))||(bt&&f.txt&&f.txt.some(t=>new RegExp(t,'i').test(tx)));if(hit){e.preventDefault();e.stopImmediatePropagation();toast('🔒 '+f.label+' dikunci admin',2000,'var(--red)');return;}}},true);
function wbpBar(){const s=wbpSess();$w('wbp-guest').style.display=s?'none':'flex';$w('wbp-in').style.display=s?'flex':'none';if(!s)return;if(s.isAdmin){$w('wbp-nm').textContent='⚙️ Admin';$w('wbp-pl').textContent='Akses penuh';$w('wbp-admbtn').style.display='';}else{$w('wbp-nm').textContent='Halo, '+s.name;let t=s.plan||'Basic';if(s.expiresAt){const d=Math.round((new Date(s.expiresAt)-new Date(wbpToday()))/864e5);t+=' · s/d '+s.expiresAt+' ('+d+' hr)';}$w('wbp-pl').textContent=t;$w('wbp-admbtn').style.display='none';}}
async function wbpCheck(){const s=wbpSess();if(!s||s.isAdmin)return;try{const all=await wbpGet(),st=wbpSet(all),f=wbpReal(all).find(x=>x.id===s.id);if(!f)return;const out=m=>{localStorage.removeItem(WBP_K_MEM);alert(m);location.reload();};if(f.status==='blocked')return out('❌ Akun diblokir admin. Hubungi: '+st.contact);if(f.status==='pending')return out('⏳ Akun belum di-ACC admin.');if(f.expiresAt&&wbpToday()>=f.expiresAt)return out('⏰ Masa aktif habis ('+f.expiresAt+'). Hubungi admin: '+st.contact);wbpSave(f,st);wbpApplyLocks();wbpBar();}catch(e){}}
// ── auth ──
function wbpMsg(m,ok){const e=$w('wbp-msg');e.style.display=m?'block':'none';e.textContent=m||'';e.style.background=ok?'#00e67618':'#f4433618';e.style.color=ok?'#00e676':'#f44336';}
function wbpOpen(t){t=t||'login';if(t==='admin'&&!$w('wbp-f-admin'))t='login';$w('wbp-auth').classList.add('on');['login','register','admin'].forEach((x,i)=>{const f=$w('wbp-f-'+x),tb=$w('wbp-at').children[i];if(f)f.style.display=x===t?'':'none';if(tb)tb.classList.toggle('on',x===t);});wbpMsg('');}
async function wbpLogin(){const hp=$w('l-hp').value.trim(),pw=$w('l-pw').value;if(!hp||!pw)return wbpMsg('No HP dan password wajib diisi.');if(_att>=5)return wbpMsg('Terlalu banyak percobaan. Muat ulang halaman.');wbpMsg('⏳ Memeriksa akun...',1);try{const all=await wbpGet(),st=wbpSet(all),m=wbpReal(all).find(x=>wbpNum(x.phone)===wbpNum(hp));if(!m||m.password!==pw){_att++;return wbpMsg('❌ Nomor HP atau password salah.');}if(m.status==='pending')return wbpMsg('⏳ Akun belum di-ACC admin. Info aktivasi dikirim lewat WhatsApp.');if(m.status==='blocked')return wbpMsg('❌ Akun diblokir admin.');if(m.expiresAt&&wbpToday()>=m.expiresAt)return wbpMsg('⏰ Masa aktif habis ('+m.expiresAt+'). Hubungi admin: '+st.contact);const seen=new Date().toLocaleString('id-ID');wbpMut(a=>a.map(x=>x.id===m.id?Object.assign({},x,{lastSeen:seen}):x)).catch(()=>{});wbpLog(m.id,m.name,'Login','Login via app');wbpSave(m,st);wbpMsg('✅ Login berhasil!',1);setTimeout(()=>location.reload(),600);}catch(e){wbpMsg('❌ Koneksi gagal: '+e.message);}}
async function wbpRegister(){const nm=$w('r-nm').value.trim(),hp=$w('r-hp').value.trim(),pw=$w('r-pw').value,p2=$w('r-pw2').value;if(!nm||!hp||!pw||!p2)return wbpMsg('Semua field wajib diisi.');const dg=hp.replace(/\D/g,'');if(dg.length<9||dg.length>15)return wbpMsg('Nomor HP tidak valid.');if(pw.length<4)return wbpMsg('Password minimal 4 karakter.');if(pw!==p2)return wbpMsg('Password tidak cocok.');wbpMsg('⏳ Mendaftarkan...',1);try{let nw=null;await wbpMut(l=>{if(wbpReal(l).some(m=>wbpNum(m.phone)===wbpNum(hp)))throw new Error('DUP');const st=wbpSet(l);nw={id:'MB'+String(wbpReal(l).length+1).padStart(3,'0')+Date.now().toString().slice(-3),name:nm,phone:hp,password:pw,plan:'Basic',joinDate:wbpToday(),status:'pending',expiresAt:wbpAdd(null,st.trial)};l.push(nw);return l;});wbpLog(nw.id,nw.name,'Registered','Daftar via app, menunggu ACC');wbpMsg('✅ Berhasil! Tunggu admin meng-ACC — info dikirim lewat WhatsApp.',1);setTimeout(()=>wbpOpen('login'),1800);}catch(e){wbpMsg(e.message==='DUP'?'❌ Nomor HP sudah terdaftar.':'❌ Koneksi gagal: '+e.message);}}
async function wbpAdminLogin(){const p=$w('a-pw').value;if(!p)return wbpMsg('Password wajib diisi.');try{const r=await fetch(WBP_WORKER+'/_admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:p})});if(r.status===401)return wbpMsg('\u274c Password admin salah.');if(r.status===429)return wbpMsg('\u23f3 Terlalu banyak percobaan salah. Coba lagi beberapa menit lagi.');if(!r.ok)return wbpMsg('\u274c Login admin belum siap di server (HTTP '+r.status+').');const d=await r.json();localStorage.setItem(WBP_K_ADM,JSON.stringify({token:d.token,exp:d.exp}));localStorage.setItem(WBP_K_MEM,JSON.stringify({id:'ADMIN',name:'Admin',plan:'Admin',isAdmin:true}));sessionStorage.setItem(WBP_K_OPEN,'1');location.reload();}catch(e){wbpMsg('\u274c Koneksi gagal. Coba lagi.');}}
function wbpLogout(){localStorage.removeItem(WBP_K_MEM);localStorage.removeItem(WBP_K_ADM);location.reload();}
// ── panel admin ──
function wbpOpenAdm(){$w('wbp-adm').style.display='block';document.body.style.overflow='hidden';wbpLoad();}
function wbpCloseAdm(){$w('wbp-adm').style.display='none';document.body.style.overflow='';}
async function wbpLoad(){try{const all=await wbpGet();WBP_ALL=wbpReal(all);WBP_ST=wbpSet(all);WBP_GL=[...WBP_ST.locked];wbpRender();wbpFillSet();wbpRenderLk();wbpRenderPw();}catch(e){alert('⚠️ Gagal memuat: '+e.message);}}
function wbpTab(t,b){['m','l','a','h','w','b','s','k'].forEach(x=>$w('wbp-p-'+x).style.display=x===t?'':'none');[...$w('wbp-mt').children].forEach(x=>x.classList.remove('on'));b.classList.add('on');if(t==='l')wbpLoadLogs();if(t==='a')wbpLoadAdminLogs();if(t==='h')wbpRenderHist();if(t==='w')wbpRenderPw();if(t==='b')wbpRenderBank();}
function wbpFil(f,b){WBP_FIL=f;[...$w('wbp-fl').children].forEach(x=>x.classList.remove('on'));b.classList.add('on');wbpRender();}
let WBP_LG=[],_pwv={},_hvo={};
const wbpRow=(ic,l,v)=>`<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--bdr);font-size:11px"><span style="color:var(--dim)">${ic} ${l}</span><span style="text-align:right">${v}</span></div>`;
const wbpEff=m=>new Set([...(WBP_ST.locked||[]),...(m.locked||[])]).size;
async function wbpGetLogs(force){if(WBP_LG.length&&!force)return WBP_LG;const r=await wbpQ(wbpLogRaw);return WBP_LG=r.logs;}
function wbpPwTog(id){_pwv[id]=!_pwv[id];wbpRender();}
async function wbpMH(id){_hvo[id]=!_hvo[id];if(_hvo[id]){try{await wbpGetLogs(true);}catch(e){}}wbpRender();}
function wbpRender(){const c=k=>WBP_ALL.filter(m=>m.status===k).length;$w('s-t').textContent=WBP_ALL.length;$w('s-a').textContent=c('active');$w('s-p').textContent=c('pending');$w('s-b').textContent=c('blocked');const q=($w('wbp-q').value||'').toLowerCase();const l=WBP_ALL.filter(m=>(WBP_FIL==='ALL'||m.status===WBP_FIL)&&(!q||[m.name,m.phone,m.id].join(' ').toLowerCase().includes(q)));$w('wbp-cards').innerHTML=l.length?l.map((m,n)=>{const d=m.expiresAt?Math.round((new Date(m.expiresAt)-new Date(wbpToday()))/864e5):null,stc=m.status==='active'?['#00e676','✅ Aktif']:m.status==='pending'?['#ffab00','⏳ Pending']:['#f44336','🚫 Blocked'];const ec=d===null?'var(--txt)':d<=0?'#f44336':d<=3?'#ffab00':'#00e676',et=m.expiresAt?m.expiresAt+(d<=0?' (HABIS)':' ('+d+' hari)'):'-';const ef=wbpEff(m);let hist='';if(_hvo[m.id]){const h=WBP_LG.filter(x=>x.memberId===m.id).slice(0,15);hist='<div style="margin-top:8px;font-size:10px">'+(h.length?h.map(x=>`<div style="padding:4px 0;border-bottom:1px solid var(--bdr)"><b style="color:var(--acc)">${wbpEsc(x.action)}</b> · ${wbpEsc(x.detail)}<br><span style="color:var(--dim)">${wbpEsc(x.time)}</span></div>`).join(''):'<span style="color:var(--dim)">Belum ada aktivitas.</span>')+'</div>';}return `<div class="wbp-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><b style="color:var(--wht);font-size:14px">${n+1}. ${wbpEsc(String(m.name).toUpperCase())}</b><span style="color:${stc[0]};border:1px solid ${stc[0]}55;background:${stc[0]}15;border-radius:20px;padding:3px 10px;font-weight:700;font-size:10px">${stc[1]}</span></div>${wbpRow('📱','No HP',`<a href="https://wa.me/${wbpNum(m.phone)}" target="_blank" style="color:var(--acc)">${wbpEsc(m.phone)}</a>`)}${wbpRow('💎','Plan',`<b style="color:var(--wht)">${wbpEsc(m.plan||'Basic')}</b>`)}${wbpRow('🔑','Password',`<span style="font-family:monospace;color:var(--wht)">${_pwv[m.id]?wbpEsc(m.password||'-'):'••••••'}</span> <button class="wbp-b" onclick="wbpPwTog('${m.id}')">👁</button>`)}${wbpRow('📅','Daftar',wbpEsc(m.joinDate||'-'))}${wbpRow('🕐','Last Seen',wbpEsc(m.lastSeen||'-'))}${wbpRow('⏱','Masa Aktif',`<b style="color:${ec}">${et}</b>`)}${wbpRow('🔒','Akses Fitur',ef?`<span style="color:#f44336">🔒 ${ef} terkunci</span>`:'<span style="color:#00e676;border:1px solid #00e67644;border-radius:20px;padding:2px 8px">✅ Semua terbuka</span>')}<button class="wbp-b" style="width:100%;margin-top:10px;padding:10px;display:flex;justify-content:space-between;font-size:12px" onclick="wbpOpenAcc('${m.id}','lock')"><span>🔒 Atur Kunci Fitur Member</span><span style="color:var(--dim);font-weight:400">${ef?ef+' terkunci':'Semua terbuka'} →</span></button><button class="wbp-b" style="width:100%;margin-top:6px;padding:10px;text-align:left;font-size:12px" onclick="wbpMH('${m.id}')">📋 History Aktivitas</button>${hist}<div class="a">${m.status==='pending'?`<button class="wbp-b wbp-g" onclick="wbpOpenAcc('${m.id}','acc')">✅ ACC</button>`:''}<button class="wbp-b wbp-c" onclick="wbpOpenAcc('${m.id}','edit')">✏️ Edit Akun</button><button class="wbp-b wbp-g" onclick="wbpWa('${m.id}')">📲 Kirim WA</button><button class="wbp-b" onclick="wbpBankJump('${m.id}')">💾 Bank</button><button class="wbp-b wbp-r" onclick="wbpStatus('${m.id}','${m.status==='blocked'?'active':'blocked'}')">${m.status==='blocked'?'🔓 Unblock':'🚫 Block'}</button><button class="wbp-b wbp-r" onclick="wbpDel('${m.id}')">🗑️ Hapus</button></div></div>`;}).join(''):'<div style="text-align:center;color:var(--dim);padding:20px">Tidak ada user ditemukan.</div>';}
async function wbpLoadLogs(){const e=$w('wbp-logs');e.innerHTML='⏳ Memuat...';try{const l=await wbpGetLogs(true);e.innerHTML=l.length?l.map(x=>`<div style="padding:6px 0;border-bottom:1px solid var(--bdr)"><b style="color:var(--acc)">${wbpEsc(x.action)}</b> · ${wbpEsc(x.memberName)}<br><span style="color:var(--dim)">${wbpEsc(x.detail)} · ${wbpEsc(x.time)}</span></div>`).join(''):'Belum ada log.';}catch(x){e.textContent='Gagal memuat log: '+x.message;}}
const wbpFind=id=>WBP_ALL.find(m=>m.id===id);
async function wbpStatus(id,to){try{let t=null;await wbpMut(l=>l.map(m=>{if(m.id===id){t=Object.assign({},m,{status:to});return t;}return m;}));if(t)wbpAdminLog(t.id,t.name,to==='blocked'?'Blocked':'Unblocked','Diubah admin');wbpLoad();}catch(e){alert('❌ '+e.message);}}
async function wbpDel(id){const m=wbpFind(id);if(!m||!confirm('Hapus "'+m.name+'"? Tidak bisa dibatalkan!'))return;try{await wbpMut(l=>l.filter(x=>x.id!==id));wbpAdminLog(m.id,m.name,'Deleted','Dihapus admin');if(m.bankBin)fetch(WBP_BASE+'/'+m.bankBin,{method:'DELETE'}).catch(()=>{});wbpLoad();}catch(e){alert('❌ '+e.message);}}
function wbpLkList(set,el){el.innerHTML=WBP_FEATS.map(f=>`<div class="wbp-lk"><span>${f.label}</span><input type="checkbox" style="width:auto" ${set.includes(f.key)?'checked':''} data-k="${f.key}"></div>`).join('');}
function wbpLkAll(id,on){$w(id).querySelectorAll('input[type=checkbox]').forEach(i=>i.checked=!!on);}
function wbpRenderLk(){const el=$w('wbp-kl');wbpLkList(WBP_GL,el);}
async function wbpSaveLocks(){const g=[...$w('wbp-kl').querySelectorAll('input:checked')].map(i=>i.dataset.k);try{await wbpMut(l=>{const r=l.filter(m=>m.id!==WBP_SID),s=l.find(m=>m.id===WBP_SID)||{id:WBP_SID};r.push(Object.assign({},s,{locked:g}));return r;});alert('✅ Kunci disimpan.');wbpLoad();}catch(e){alert('❌ '+e.message);}}
function wbpFillSet(){const s=WBP_ST;$w('st-trial').value=s.trial;$w('st-contact').value=s.contact;s.pkgs.forEach((p,i)=>{$w('st-l'+i).value=p.l;$w('st-p'+i).value=p.p;});$w('st-pay').value=s.pay;}
async function wbpSaveSet(){const g=id=>$w(id).value.trim(),d=wbpSet([]);const pkgs=[0,1,2].map(i=>({l:g('st-l'+i)||d.pkgs[i].l,p:g('st-p'+i)||d.pkgs[i].p}));try{await wbpMut(l=>{const r=l.filter(m=>m.id!==WBP_SID),s=l.find(m=>m.id===WBP_SID)||{id:WBP_SID};r.push(Object.assign({},s,{trial:Math.max(0,parseInt(g('st-trial'),10)||0),contact:g('st-contact')||d.contact,pkgs,pay:g('st-pay')||d.pay}));return r;});alert('✅ Pengaturan disimpan.');wbpLoad();}catch(e){alert('❌ '+e.message);}}
// ── modal ACC / edit / kunci per member ──
function wbpOpenAcc(id,mode){const m=wbpFind(id);if(!m)return alert('Member tidak ditemukan. Tap 🔄 dulu.');const st=WBP_ST,isAcc=mode==='acc',isLk=mode==='lock';WBP_ACC={id,mode};$w('ac-t').textContent=(isAcc?'✅ ACC — ':isLk?'🔒 Kunci Fitur — ':'✏️ Edit — ')+m.name;$w('ac-s').textContent='📱 '+m.phone;$w('ac-main').style.display=isLk?'none':'';$w('ac-lk').style.display=isLk?'':'none';$w('ac-save').textContent=isAcc?'✅ ACC':isLk?'💾 Simpan Kunci':'💾 Simpan';if(isLk){$w('ac-lk').innerHTML='<div style="display:flex;gap:6px;margin-bottom:6px"><button class="wbp-b wbp-r" style="flex:1" onclick="wbpLkAll(\'ac-lkl\',1)">🔒 Kunci Semua</button><button class="wbp-b wbp-g" style="flex:1" onclick="wbpLkAll(\'ac-lkl\',0)">🔓 Buka Semua</button></div><div style="font-size:10px;color:var(--dim);margin-bottom:6px">⚡ Khusus member ini — kunci global tetap berlaku terpisah.</div><div id="ac-lkl"></div>';wbpLkList(m.locked||[],$w('ac-lkl'));}else{const plans=['Basic',...st.pkgs.map(p=>p.l)];if(!plans.includes(m.plan))plans.push(m.plan);$w('ac-plan').innerHTML=plans.map(p=>`<option>${wbpEsc(p)}</option>`).join('');$w('ac-plan').value=m.plan||'Basic';$w('ac-pw').value=m.password||String(Math.floor(1e5+Math.random()*9e5));let ex=m.expiresAt||'';if(isAcc){const t=wbpAdd(null,st.trial);if(!ex||ex<t)ex=t;}$w('ac-exp').value=ex;$w('ac-lim').value=m.bankLimit||'';$w('ac-wa').checked=true;}$w('wbp-acc').classList.add('on');}
function wbpAddD(n){const e=$w('ac-exp');e.value=wbpAdd(e.value||'',n);}
async function wbpAccSave(){const {id,mode}=WBP_ACC;try{let after=null;if(mode==='lock'){const lk=[...$w('ac-lk').querySelectorAll('input:checked')].map(i=>i.dataset.k);await wbpMut(l=>l.map(m=>m.id===id?(after=Object.assign({},m,{locked:lk})):m));wbpAdminLog(id,after&&after.name,'Lock','Kunci fitur: '+(lk.join(', ')||'tidak ada'));}else{const pw=$w('ac-pw').value.trim(),plan=$w('ac-plan').value,exp=$w('ac-exp').value,lr=$w('ac-lim').value.trim(),lim=lr===''?null:parseInt(lr,10);if(pw.length<4)return alert('Password minimal 4 karakter.');if(!/^\d{4}-\d{2}-\d{2}$/.test(exp))return alert('Pilih masa aktif lewat kalender.');if(lim!==null&&!(lim>=1&&lim<=300))return alert('Batas bank 1–300 atau kosongkan.');await wbpMut(l=>l.map(m=>{if(m.id!==id)return m;after=Object.assign({},m,{password:pw,plan,expiresAt:exp,status:mode==='acc'?'active':m.status});if(lim===null)delete after.bankLimit;else after.bankLimit=lim;return after;}));wbpAdminLog(id,after.name,mode==='acc'?'Activated':'EditAccount','Admin: '+plan+' s/d '+exp);if($w('ac-wa').checked)wbpWaBar(after);}
$w('wbp-acc').classList.remove('on');wbpLoad();}catch(e){alert('❌ '+e.message);}}
function wbpWaBar(m){const st=WBP_ST,msg=`Halo ${m.name}, akun WongBagus kamu:\n\nLogin: ${location.origin+location.pathname}\nNo WA: ${m.phone}\nPassword: ${m.password}\nPaket: ${m.plan||'Basic'}\nMasa aktif sampai: ${m.expiresAt||'-'}\n\nPerpanjangan:\n${st.pkgs.map(p=>'- '+p.l+': '+p.p).join('\n')}\n\nTransfer: ${st.pay}\nKirim bukti ke admin ya 🙏 (${st.contact})`;let b=$w('wbp-wabar');if(!b){b=document.createElement('div');b.id='wbp-wabar';b.style.cssText='position:fixed;left:12px;right:12px;bottom:12px;z-index:100000;background:#16a34a;border-radius:10px';document.body.appendChild(b);}b.innerHTML=`<a href="https://wa.me/${wbpNum(m.phone)}?text=${encodeURIComponent(msg)}" target="_blank" style="display:block;padding:14px;text-align:center;color:#fff;font-weight:800;text-decoration:none">📲 Tap untuk kirim WA ke ${wbpEsc(m.name)}</a><button onclick="this.parentElement.remove()" style="width:100%;padding:6px;background:none;color:#dcfce7;font-size:11px">Tutup</button>`;}
function wbpWa(id){const m=wbpFind(id);if(m&&m.password)wbpWaBar(m);else alert('Belum ada password — ACC dulu.');}

// ── admin: History, Passwords, Bank ──
async function wbpRenderHist(){const el=$w('wbp-hl');el.innerHTML='<div style="padding:12px;color:var(--dim)">⏳ Memuat history...</div>';try{await wbpGetLogs(true);}catch(e){el.innerHTML='<div style="padding:12px;color:#f44336">Gagal memuat: '+wbpEsc(e.message)+'</div>';return;}const q=($w('wbp-hq').value||'').toLowerCase(),g={};WBP_LG.forEach(x=>{const k=x.memberId||'?';(g[k]=g[k]||{name:x.memberName,items:[]}).items.push(x);});const ks=Object.keys(g).filter(k=>!q||(k+' '+g[k].name).toLowerCase().includes(q));el.innerHTML=ks.length?ks.map(k=>`<div class="wbp-card"><div style="display:flex;justify-content:space-between"><b style="color:var(--wht)">${wbpEsc(g[k].name)}</b><span style="font-size:10px;color:var(--dim)">${wbpEsc(k)} · ${g[k].items.length} aktivitas</span></div><div style="margin-top:6px;font-size:10px">${g[k].items.slice(0,8).map(x=>`<div style="padding:4px 0;border-bottom:1px solid var(--bdr)"><b style="color:var(--acc)">${wbpEsc(x.action)}</b> · ${wbpEsc(x.detail)}<br><span style="color:var(--dim)">${wbpEsc(x.time)}</span></div>`).join('')}</div></div>`).join(''):'<div style="padding:12px;color:var(--dim);text-align:center">Belum ada history.</div>';}
function wbpCopy(t){try{navigator.clipboard.writeText(t);toast('📋 Tersalin');}catch(e){prompt('Salin:',t);}}
function wbpRenderPw(){const el=$w('wbp-pwl'),q=($w('wbp-pq').value||'').toLowerCase();const l=WBP_ALL.filter(m=>!q||[m.name,m.id,m.phone].join(' ').toLowerCase().includes(q));el.innerHTML=l.length?l.map(m=>`<div class="wbp-card"><div style="display:flex;justify-content:space-between"><b style="color:var(--wht)">${wbpEsc(m.name)}</b><span style="font-size:10px;color:var(--dim)">${wbpEsc(m.id)}</span></div><div style="font-size:10px;color:var(--dim);margin:3px 0 6px">📱 ${wbpEsc(m.phone)} · ${wbpEsc(m.plan||'Basic')}</div><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-family:monospace;font-size:14px;color:var(--amb)">${wbpEsc(m.password||'-')}</span><button class="wbp-b wbp-c" onclick="wbpCopy('${wbpEsc(String(m.password||'').replace(/'/g,''))}')">📋 Salin</button></div></div>`).join(''):'<div style="padding:12px;color:var(--dim);text-align:center">Tidak ada member.</div>';}
let _bv={},_bo={};
const wbpUnp=it=>{if(!it||!Array.isArray(it.tr))return it;const o=Object.assign({},it);delete o.tr;o.trekRows=it.tr.map(r=>({result:r[0],predStr:r[1],hit:r[2]===null?null:!!r[2]}));return o;};
async function wbpBankLoad(id){const m=wbpFind(id);if(!m)return;_bv[id]={loading:true};wbpRenderBank();try{if(!m.bankBin){_bv[id]={items:[],at:''};}else{const d=await jq('GET','/'+m.bankBin+'/latest'),o=(d&&d.record&&d.record.data)||d.record||{};_bv[id]={items:Object.keys(o).filter(a=>Array.isArray(o[a])).flatMap(a=>o[a].map(wbpUnp)),at:o.updatedAt?new Date(o.updatedAt).toLocaleString('id-ID'):''};}}catch(e){_bv[id]={err:e.message};}_bo[id]=true;wbpRenderBank();}
async function wbpBankAll(){if(WBP_ALL.length>15&&!confirm('Memuat '+WBP_ALL.length+' bank memakai '+WBP_ALL.length+' request server. Lanjut?'))return;for(const m of WBP_ALL)await wbpBankLoad(m.id);}
function wbpBankTog(id){_bo[id]=!_bo[id];wbpRenderBank();}
function wbpBankJump(id){wbpTab('b',$w('wbp-mt').children[4]);wbpBankLoad(id);}
async function wbpBankClear(id){const m=wbpFind(id);if(!m||!m.bankBin)return alert('Member ini belum punya bank.');if(!confirm('Kosongkan SEMUA rumus bank milik "'+m.name+'"? Tidak bisa dibatalkan!'))return;try{await jq('PUT','/'+m.bankBin,{data:{owner:m.name,updatedAt:new Date().toISOString(),clearedByAdmin:new Date().toISOString()}});wbpAdminLog(m.id,m.name,'BankCleared','Bank dikosongkan admin');await wbpBankLoad(id);}catch(e){alert('❌ '+e.message);}}
function wbpRenderBank(){const el=$w('wbp-bl');if(!el)return;const q=($w('wbp-bq').value||'').toLowerCase();const l=WBP_ALL.filter(m=>!q||[m.name,m.phone,m.id].join(' ').toLowerCase().includes(q));if(!l.length){el.innerHTML='<div style="text-align:center;color:var(--dim);padding:20px">Tidak ada member.</div>';return;}el.innerHTML=l.map((m,n)=>{const v=_bv[m.id]||{},open=_bo[m.id],lim=m.bankLimit||100;let info='<span style="color:var(--dim)">Belum dimuat</span>';if(v.loading)info='⏳ Memuat...';else if(v.err)info='<span style="color:#f44336">❌ '+wbpEsc(v.err)+'</span>';else if(v.items){const it=v.items,h=it.filter(b=>b.status==='hit').length,p=it.filter(b=>b.status==='patah').length,w=it.length-h-p;info=`<b style="font-size:13px;color:var(--wht)">${it.length}/${lim} rumus</b> <span style="color:#00e676">✅ ${h}</span> <span style="color:#f44336">❌ ${p}</span> <span style="color:#ffab00">⏳ ${w}</span>`+(v.at?`<div style="color:var(--dim);font-size:10px;margin-top:2px">Update: ${wbpEsc(v.at)}</div>`:'');}let body='';if(open&&v.items){if(!v.items.length)body='<div style="color:var(--dim);font-size:10px;padding:8px 0">Bank kosong.</div>';else{const g={};v.items.forEach(b=>{const k=b.mktName||b.mkt||'Lainnya';(g[k]=g[k]||[]).push(b);});body='<div style="border-top:1px solid var(--bdr);margin-top:8px"></div>'+Object.keys(g).sort().map(k=>`<div style="margin-top:8px"><div style="color:var(--acc);font-weight:700;font-size:12px">${wbpEsc(k)} <span style="color:var(--dim);font-weight:400">· ${g[k].length} rumus</span></div>${g[k].map(b=>{const sc=b.status==='hit'?['#00e676','HIT']:b.status==='patah'?['#f44336','PATAH']:['#ffab00','PENDING'],dt=String(b.savedAt||'').includes('/')?String(b.savedAt).split('/').slice(0,2).map(x=>x.padStart(2,'0')).join('/'):(b.savedAt||'');return `<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--bdr)"><div style="min-width:0"><div style="font-family:monospace;font-size:12px;color:var(--wht);word-break:break-all">${wbpEsc(b.key)}</div><div style="font-size:10px;color:var(--dim)">Trek ${b.streak||0}× · ${b.nDigit||2}D · ${wbpEsc(b.scanMode||'ai_ke')} · ${wbpEsc(dt)}</div></div><div style="text-align:right;flex-shrink:0"><div style="font-size:15px;font-weight:900;color:var(--amb)">${b.curPred?wbpEsc(b.curPred.join('')):'??'}</div><div style="font-size:10px;font-weight:700;color:${sc[0]}">${sc[1]}</div></div></div>`;}).join('')}</div>`).join('');}}return `<div class="wbp-card"><div style="display:flex;justify-content:space-between"><b style="color:var(--wht);font-size:14px">${n+1}. ${wbpEsc(String(m.name).toUpperCase())}</b><span style="font-size:11px;color:var(--dim)">${wbpEsc(m.phone)}</span></div><div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px"><div>${info}</div><div style="display:flex;gap:5px;flex-shrink:0"><button class="wbp-b wbp-c" onclick="wbpBankLoad('${m.id}')">${v.items?'↻':'📥 Muat'}</button>${v.items?`<button class="wbp-b" onclick="wbpBankTog('${m.id}')">${open?'Tutup':'Lihat'}</button><button class="wbp-b wbp-r" onclick="wbpBankClear('${m.id}')">🗑</button>`:''}</div></div>${body}</div>`;}).join('');}
// ═════ WB_BANK: bank rumus per member untuk Scan 1–5, disimpan lewat Worker ═════
(function(){
 const LS='wbp_bank@'+WBP_ACCT+'__',CAPS=[1e9,12,8,5,3];
 const sess=()=>wbpSess(),isMem=()=>{const u=sess();return !!(u&&!u.isAdmin&&u.id);};
 const who=()=>{const u=sess();return u?String(u.phone||u.id).toLowerCase().replace(/[^a-z0-9]/g,'_'):'guest';};
 const pre=()=>LS+who()+'__',k=a=>pre()+(a||'d');
 let ready=false,dirty=new Set(),timer=null,chain=Promise.resolve(),binId=null,cbs=[];
 const rd=a=>{try{return JSON.parse(localStorage.getItem(k(a))||'[]');}catch{return[];}};
 const pack=(it,c)=>{if(!it||!Array.isArray(it.trekRows))return it;const o=Object.assign({},it);delete o.trekRows;o.tr=it.trekRows.slice(-c).map(r=>[r.result,r.predStr,r.hit===null||r.hit===undefined?null:(r.hit?1:0)]);return o;};
 const unpack=it=>{if(!it||!Array.isArray(it.tr))return it;const o=Object.assign({},it);delete o.tr;o.trekRows=it.tr.map(r=>({result:r[0],predStr:r[1],hit:r[2]===null?null:!!r[2]}));return o;};
 const lim=()=>{const u=sess();if(!u||u.isAdmin)return 0;const n=parseInt(u.bankLimit,10);return n>0?n:(CFG.BANK_LIMIT_DEFAULT||100);};
 const page=a=>String(a||'d').split('_')[0];
 const apps=()=>{const p=pre(),o=[];for(let i=0;i<localStorage.length;i++){const x=localStorage.key(i);if(x&&x.indexOf(p)===0)o.push(x.slice(p.length));}return o;};
 const pageCount=pg=>apps().filter(a=>page(a)===pg).reduce((s,a)=>s+rd(a).length,0);
 async function ensureBin(){if(binId)return binId;const u=sess(),all=await wbpGet(),m=wbpReal(all).find(x=>x.id===u.id);if(!m)throw new Error('Akun tidak ditemukan');if(m.bankBin)return binId=m.bankBin;const d=await jq('POST','',{data:{owner:m.name}},{'X-Bin-Name':'wb-bank-'+m.id,'X-Bin-Private':'true'});const nb=d&&d.metadata&&d.metadata.id;if(!nb)throw new Error('Gagal membuat bin bank');let win=nb;await wbpMut(l=>{const t=l.find(x=>x.id===m.id);if(!t)return l;if(t.bankBin){win=t.bankBin;return l;}t.bankBin=nb;return l;});if(win!==nb)fetch(WBP_BASE+'/'+nb,{method:'DELETE'}).catch(()=>{});return binId=win;}
 // push: baca isi server dulu lalu gabung — scan lain / perangkat lain tidak tertimpa
 async function push(){if(!isMem()){dirty.clear();return;}const ds=[...dirty];dirty.clear();if(!ds.length)return;
  try{const b=await ensureBin(),d=await jq('GET','/'+b+'/latest'),srv=(d&&d.record&&d.record.data)||d.record||{};let cur;
   for(const c of CAPS){cur=Object.assign({},srv);ds.forEach(a=>{if(localStorage.getItem(k(a))===null)delete cur[a];else cur[a]=rd(a).map(i=>pack(i,c));});cur.updatedAt=new Date().toISOString();cur.owner=sess().name;if(JSON.stringify({data:cur}).length<=190000)break;}
   await jq('PUT','/'+b,{data:cur});}
  catch(e){ds.forEach(a=>dirty.add(a));try{toast('⚠️ Bank tersimpan di HP, gagal ke server: '+e.message,3000,'var(--red)');}catch{}}}
 const sched=()=>{clearTimeout(timer);timer=setTimeout(()=>{chain=chain.then(push);},1500);};
 const flush=()=>{clearTimeout(timer);if(dirty.size)chain=chain.then(push);};
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flush();});window.addEventListener('pagehide',flush);
 const fin=()=>{ready=true;cbs.splice(0).forEach(c=>{try{c();}catch(e){console.error(e);}});};
 (async()=>{if(!isMem())return fin();
  try{const u=sess(),all=await wbpGet(),m=wbpReal(all).find(x=>x.id===u.id);
   if(m&&m.bankBin){binId=m.bankBin;const d=await jq('GET','/'+binId+'/latest'),o=(d&&d.record&&d.record.data)||d.record||{};
    Object.keys(o).forEach(a=>{if(Array.isArray(o[a])&&!dirty.has(a))localStorage.setItem(k(a),JSON.stringify(o[a].map(unpack)));});
    apps().forEach(a=>{if(!Array.isArray(o[a])&&!dirty.has(a))localStorage.removeItem(k(a));});}
   else{const la=apps().filter(a=>rd(a).length);la.forEach(a=>dirty.add(a));if(la.length)flush();}}
  catch(e){try{toast('⚠️ Bank belum sinkron — memakai salinan di HP',3000);}catch{}}
  fin();})();
 window.WB_BANK={
  onReady:(cb)=>{if(ready){try{cb();}catch(e){console.error(e);}}else cbs.push(cb);},
  isReady:()=>ready,getSync:a=>rd(a),limit:lim,pageCount,listAppsSync:apps,
  room:(a,n)=>{const l=lim();return l?Math.min(n,Math.max(0,l-pageCount(page(a)))):n;},
  clearSync:a=>{try{localStorage.removeItem(k(a));}catch{return false;}dirty.add(a||'d');sched();return true;},
  setSync:(data,a)=>{const l=lim(),cur=rd(a).length;if(l&&Array.isArray(data)&&data.length>cur&&(pageCount(page(a))-cur+data.length)>l){try{toast('⚠️ Bank penuh (batas '+l+' rumus per scan)',2500,'var(--red)');}catch{}return false;}try{localStorage.setItem(k(a),JSON.stringify(data||[]));}catch{return false;}dirty.add(a||'d');sched();return true;}};
})();

 // ── init (setelah DOM siap) ──
  const wbmHash=()=>String(CFG.ADMIN_HASH===undefined?'#admin':CFG.ADMIN_HASH).toLowerCase();
 function wbmAdminShow(){if($w('wbp-f-admin'))return;$w('wbp-at').insertAdjacentHTML('beforeend',WBM_ADMIN_TAB);$w('wbp-msg').insertAdjacentHTML('beforebegin',WBM_ADMIN_FORM);}
 function wbmAdminHash(){const h=wbmHash(),s=wbpSess();if(!h||(s&&s.isAdmin))return;if(location.hash.toLowerCase()===h){wbmAdminShow();wbpOpen('admin');}}
function wbmCloseAuth(){if(wbpSess())$w('wbp-auth').classList.remove('on');}
 function wbmMount(){
  if(!document.getElementById('wbm-css')){const s=document.createElement('style');s.id='wbm-css';s.textContent=WBM_CSS;document.head.appendChild(s);}
  const box=document.createElement('div');box.id='wbm-root';box.innerHTML=WBM_MODALS;
  while(box.firstChild)document.body.appendChild(box.firstChild);
  const bar=document.createElement('div');bar.innerHTML=WBM_BAR;
  while(bar.lastChild)document.body.insertBefore(bar.lastChild,document.body.firstChild);
  wbpBar();wbpApplyLocks();
  if(!wbmHash())wbmAdminShow();
  if(!wbpSess())wbpOpen('login');else{wbpCheck();setInterval(wbpCheck,5*60*1000);if(wbpIsAdm()&&sessionStorage.getItem(WBP_K_OPEN)){sessionStorage.removeItem(WBP_K_OPEN);wbpOpenAdm();}}
  wbmAdminHash();window.addEventListener('hashchange',wbmAdminHash);
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wbmMount);else wbmMount();

window.wbmCloseAuth=wbmCloseAuth;
